_data = np.load(_asset_path())
H1_STRAIN = _data["h1_strain"].astype(np.float64)
L1_STRAIN = _data["l1_strain"].astype(np.float64)
FS = float(_data["sample_rate_hz"])
GPS_START = float(_data["gps_start"])
